				rightPanel.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
			}
			@Override public void mouseExited(MouseEvent e)
			{
				panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				rightPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
			@Override public void mouseClicked(MouseEvent e) { onMaterialClick.accept(mat.name); }
		});

		return panel;
	}

	private JPanel buildMemberRow(String name, MemberResult result)
	{
		JPanel panel = new JPanel(new BorderLayout(8, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(4, 8, 4, 8));
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));

		JLabel nameLabel = new JLabel(name);
		nameLabel.setForeground(Color.WHITE);

		JPanel rightPanel = new JPanel();
		rightPanel.setLayout(new BoxLayout(rightPanel, BoxLayout.Y_AXIS));
		rightPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		switch (result.status)
		{
			case CAN_CRAFT:
			{
				JLabel statusLabel = new JLabel("✔ Can craft");
				statusLabel.setForeground(new Color(0, 200, 0));
				statusLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);
				rightPanel.add(statusLabel);
				break;
			}
			case CANNOT_CRAFT:
			{
				JLabel statusLabel = new JLabel("✘ " + result.missingSkill.getName() + " " + result.requiredLevel);
				statusLabel.setForeground(new Color(220, 50, 50));
				statusLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);

				JLabel subLabel = new JLabel("Current: " + result.currentLevel);
				subLabel.setForeground(Color.GRAY);
				subLabel.setFont(subLabel.getFont().deriveFont(11f));
				subLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);

				rightPanel.add(statusLabel);
				rightPanel.add(subLabel);
				break;
			}
			default:
			{
				JLabel statusLabel = new JLabel("Unknown");
				statusLabel.setForeground(Color.GRAY);
				statusLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);
				rightPanel.add(statusLabel);
				break;
			}
		}

		panel.add(nameLabel, BorderLayout.WEST);
		panel.add(rightPanel, BorderLayout.EAST);
		return panel;
	}
}

package com.WhoCanCraft;

import net.runelite.client.hiscore.HiscoreSkill;

class MemberResult
{
	enum Status { CAN_CRAFT, CANNOT_CRAFT, UNKNOWN }

	final Status status;
	final HiscoreSkill missingSkill;
	final int requiredLevel;
	final int currentLevel;

	private MemberResult(Status status, HiscoreSkill missingSkill, int requiredLevel, int currentLevel)
	{
		this.status = status;
		this.missingSkill = missingSkill;
		this.requiredLevel = requiredLevel;
		this.currentLevel = currentLevel;
	}

	static MemberResult canCraft()
	{
		return new MemberResult(Status.CAN_CRAFT, null, 0, 0);
	}

	static MemberResult cannotCraft(HiscoreSkill skill, int requiredLevel, int currentLevel)
	{
		return new MemberResult(Status.CANNOT_CRAFT, skill, requiredLevel, currentLevel);
	}

	static MemberResult unknown()
	{
		return new MemberResult(Status.UNKNOWN, null, 0, 0);
	}
}

